class AuthMiddleware:
    """Check bearer tokens before protected handlers run."""

    def verify_token(self, request):
        """Validate a request token and return its claims."""
        token = extract_token(request.headers)
        return decode_jwt(token)

def verify_token(self, request):
    """Validate a request token and return its claims."""
    token = extract_token(request.headers)
    return decode_jwt(token)

def protected_route(request):
    middleware = AuthMiddleware()
    return middleware.verify_token(request)

def extract_token(headers):
    """Read a bearer token from request headers."""
    return headers.get("Authorization", "").removeprefix("Bearer ")

def decode_jwt(token):
    """Decode and validate a signed JWT."""
    return jwt.decode(token, "development-secret", algorithms=["HS256"])

def validate_payment(amount, currency):
    """Reject invalid payment requests before charging."""
    if amount <= 0 or not currency:
        raise ValueError("invalid payment")

def charge_card(card, amount):
    """Submit a card charge to the payment provider."""
    return {"card": card, "amount": amount, "status": "charged"}

def process_payment(card, amount, currency):
    validate_payment(amount, currency)
    return charge_card(card, amount)

def resize_image(image, width, height):
    """Resize an uploaded image to the requested dimensions."""
    return image.resize((width, height))

def upload_to_storage(image, bucket):
    """Save image bytes to object storage."""
    return bucket.put_object(image)

def upload_image(image, bucket):
    resized = resize_image(image, 640, 480)
    return upload_to_storage(resized, bucket)

def hash_password(password, salt):
    """Hash a user's password with a salt before storing credentials."""
    salted_password = (salt + password).encode("utf-8")
    return hashlib.sha256(salted_password).hexdigest()
